import {createRoot} from 'react-dom/client';
import {Home,PenLine,TrendingUp,ChartNoAxesCombined,SlidersHorizontal,Settings,UserRound,ArrowUpRight,Plus,RefreshCw,Upload,ChevronRight,X,Check,Search,Database,Sun,Download,FileText,Image as ImageIcon,Clock,TriangleAlert,Menu,Bot,Bookmark,QrCode,LogOut,Lightbulb,Eye,Heart,Star,MessageCircle,ArrowLeft,ArrowRight,ExternalLink,Play,RotateCcw,Trash2,Share2,Signal,Wifi,BatteryFull,BookOpenCheck,Link2,Sparkles,CircleGauge} from 'lucide-react';
