function SettingsPage(s:Shared){
 const {data:providers}=useData('/providers',s.tick),{data:storage}=useData('/storage',s.tick);
 const [keys,setKeys]=useState<Data>({}),[saving,setSaving]=useState('');
 const save=async(provider:string)=>{
  setSaving(provider);
  try{
   const body=provider==='tikhub'?{key:keys.tikhub}:{secret_id:keys.secret_id,secret_key:keys.secret_key};
   const result=await s.act(()=>api('/providers/'+provider+'/key','PUT',body));
   setKeys({});
   s.notify(result.status==='verified'?'凭据已保存，连接验证通过':'凭据已保存，'+(result.validation_error||states[result.status]));
  }catch{}finally{setSaving('')}
 };
 return <><Heading title="数据源设置"/><div className="form-grid">
  {['tikhub','tencent-ocr'].map(provider=>{
   const current=providers?.find((x:Data)=>x.provider===provider);
   const isTikHub=provider==='tikhub';
   return <section className="card form-card service-card" key={provider}>
    <div className="flex"><span className="service-logo">{isTikHub?'T':'云'}</span><div><h2>{isTikHub?'TikHub':'腾讯云 OCR'}</h2><small>{isTikHub?'四平台热点选题搜索':'后台截图识别'}</small></div></div>
    <Pill warn={current?.status!=='verified'}>{states[current?.status]||'未配置'}</Pill>
    <div className="service-error">{current?.validation_error&&<p className="red" role="alert">{current.validation_error}</p>}</div>
    <div className="service-fields">{(isTikHub?[['tikhub','API Key']]:[['secret_id','SecretId'],['secret_key','SecretKey']]).map(([key,label])=><Field label={label} key={key}><input type="password" autoComplete="new-password" value={keys[key]||''} onChange={e=>setKeys({...keys,[key]:e.target.value})} placeholder={current?.mask||'输入凭据'}/></Field>)}</div>
    <div className="actions"><button className="btn primary" disabled={saving===provider} onClick={()=>save(provider)}>{saving===provider?'保存并验证中…':'保存并验证'}</button><button className="btn" onClick={()=>s.act(()=>api('/providers/'+provider+'/key','DELETE'),'配置已移除').catch(()=>{})}>移除配置</button></div>
    <small className="service-help">{isTikHub?'保存时使用“AI实战”验证一次抖音内容搜索；热点选题按关注领域逐词调用，可能计费。':'保存后自动用测试图片验证一次，不使用业务截图；计入每日上限，可能产生 OCR 费用。'}</small>
   </section>
  })}
  <section className="card span-two"><div className="between"><div><h2>本地素材与数据</h2><small>{storage?.database}</small></div><button className="btn" onClick={()=>s.act(()=>api('/storage/backup','POST'),'数据库备份完成（不含媒体）').catch(()=>{})}><Database size={16}/>备份数据库</button></div><div className="storage-stats"><span><b>{storage?.contents||0}</b> 篇历史原稿（已停用）</span><span>剩余 <b>{storage?number(storage.free/1024**3):'—'}</b> GB</span></div></section>
 </div><CallBudgets {...s}/></>;
}
