 const suggestions=[...(analysis.p0||[]).map((x:Data)=>({...x,level:'P0'})),...(analysis.p1||[]).map((x:Data)=>({...x,level:'P1'}))];
 const [chosen,setChosen]=useState<number[]>(suggestions.map((_:Data,i:number)=>i)),[experienceIds,setExperienceIds]=useState<string[]>([]),[thoughts,setThoughts]=useState(''),[pending,setPending]=useState(''),[planId,setPlanId]=useState(''),[mode,setMode]=useState('detail'),[slide,setSlide]=useState(0);
 useEffect(()=>{if(!pending)return;const job=s.jobs.find(j=>j.id===pending);if(job?.state==='completed'&&job.result?.id){setPlanId(job.result.id);setPending('');s.refresh();s.notify('优化版图文已生成')}},[s.jobs,pending]);
 const plan=(plans||[]).find((x:Data)=>x.id===planId),preview=plan?.metadata?.preview;const images=Array.from(new Set([post.cover_url,...(post.detail_media||[]).filter((x:Data)=>x.type==='image').map((x:Data)=>x.url)].filter(Boolean))) as string[];
